{"code": "import os
from hermes_tools import search_files

# List all files in the books directory with full paths
result = search_files(pattern="*", target="files", path="/home/bob/books")
matches = result.get('matches', [])

# Group by directory
dirs = {}
for match in matches:
    path = match['path']
    dirname = os.path.dirname(path)
    if dirname not in dirs:
        dirs[dirname] = []
    dirs[dirname].append(path)

# Print structure
for dirname, files in sorted(dirs.items()):
    print(f"\n{dirname}/")
    for f in sorted(files)[:10]:  # Limit to 10 per dir
        print(f"  {os.path.basename(f)}")
    if len(files) > 10:
        print(f"  ... and {len(files) - 10} more")"}

